INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "フリーマーケット会場", 1, 2, 8, 2834, "ペコリーヌとの出会い", 10118, 0, 91002, 5118061, "青空の下で謁見", 7, 20063115, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "フリーマーケット会場", 1, 2, 8, 2835, "マホとの出会い", 10118, 0, 91002, 5118062, "未来の騎空団\nマスコット？", 7, 20063115, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "ランドソル市街地", 1, 2, 8, 2837, "アキノとの出会い", 10118, 0, 91002, 5118063, "お嬢さまからの\n緊急依頼", 7, 20063115, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "フリーマーケット会場", 1, 2, 8, 4108402, "ジュンとの出会い", 10118, 0, 91002, 5118064, "黄金色の悩みごと", 18, 20063115, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "フリーマーケット会場", 1, 2, 8, 4107402, "カオリとの出会い", 10118, 0, 91002, 5118065, "白熱！　格闘大会！", 18, 20063115, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "オーエド町", 1, 2, 8, 9000227, "ニノンとの出会い", 10118, 1, 91002, 5118066, "祭り太鼓はオーエドの華", 16, 20063115, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "フリーマーケット会場", 1, 3, 8, 2101181, "スズナとの出会い", 10118, 0, 91002, 5118067, "人気者は遅れて\nやってくる", 19, 20063115, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "ランドソル市街地", 1, 3, 8, 4109402, "ナナカとの出会い", 10118, 0, 91002, 5118068, "巫女・ミーツ・魔法少女", 18, 20063115, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "フリーマーケット会場", 1, 3, 8, 4305402, "キャル＆コッコロとの出会い", 10118, 0, 91002, 5118069, "ネズ耳は二度なくなる", 18, 20063115, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "ランドソル市街地", 1, 3, 8, 4101402, "ユカリとの出会い", 10118, 0, 91002, 5118070, "この出会いにカンパイ！", 18, 20063115, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "ランドソル市街地", 1, 3, 8, 4106402, "アオイとの出会い", 10118, 0, 91002, 5118071, "陰陽アンサンブル", 18, 20063115, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (40, "フリーマーケット会場", 1, 3, 8, 2836, "シノブとの出会い", 10118, 1, 91002, 5118072, "運試し十番勝負！", 7, 20063115, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。");
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES (0, 0, 0, 1, 0, 0, "オープニング", 10118, 0, 0, 5118600, "彼女たちの新たな日常", 0, 20063115, 0);
